    except (KeyError, TypeError):
        return 400, {"error": "tenant_id and email are required"}
    if not isinstance(email, str) or "@" not in email:
        return 400, {"error": "email must be an address"}
    key = email_key(email)
    existing = db.find_active(tenant, key)
